# Compromise: combine: only enclose-comps, sized >= some count, plus edge-touching? d1 8-comp touches edge! d2 7-comp touches edge. So edge-touched hole possible.
# Decide: use the RANK rule variant where color=8 for LARGEST comp(s), 7 for smallest comp, everything else 0. Check demos: d1: largest10->8 ✓, smallest1->7 ✓, others 0 ✓ (no mismatches? earlier rank run had 15+ bad cells due to a bug: it filled 7s for OTHER comps). Fix: only ONE comp gets 7 (the unique smallest). d1 smallest=1 ✓. d2 smallest=2 ✓. d3 smallest=4 ✓. And 8 = largest. Verify computationally on all three demos first.
def solve_rank2(A):
    H,W=len(A),len(A[0]); O=[row[:] for row in A]
    vis=[[False]*W for _ in range(H)]
    comps=[]
    for r in range(H):
        for c in range(W):
            if A[r][c]==0 and not vis[r][c]:
                st=[(r,c)]; vis[r][c]=True; comp=[(r,c)]
                while st:
                    x,y=st.pop()
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            nx,ny=x+dx,y+dy
                            if 0<=nx<H and 0<=ny<W and A[nx][ny]==0 and not vis[nx][ny]:
                                vis[nx][ny]=True; st.append((nx,ny)); comp.append((nx,ny))
                comps.append(comp)
    mx=max(len(c) for c in comps); mn=min(len(c) for c in comps)
    for comp in comps:
        if len(comp)==mx:
            for p in comp: O[p[0]][p[1]]=8
        elif len(comp)==mn:
            for p in comp: O[p[0]][p[1]]=7
    return O
ok=all(solve_rank2(I)==O_ for name,I,O_ in [('d1',G['Demo pair 1 input'],G['Demo pair 1 output']),('d2',G['Demo pair 2 input'],G['Demo pair 2 output']),('d3',G['Demo pair 3 input'],G['Demo pair 3 output'])])
print('rank2 ok:',ok)
for name,I,O_ in [('d1',G['Demo pair 1 input'],G['Demo pair 1 output']),('d2',G['Demo pair 2 input'],G['Demo pair 2 output']),('d3',G['Demo pair 3 input'],G['Demo pair 3 output']):
